     \begin{equation}
         D^{\text{sparse}}_\bullet \xrightarrow{\rho} D^{\text{gauged}}_\bullet \xrightarrow{\pi} D^{\text{dense}}_\bullet \xrightarrow{\gamma} C_\bullet
