     \begin{align}
         H_1(D^{\text{sparse}}) &\xrightarrow[{[\rho_1]}]{\sim} H_1(D^{\text{gauged}}) \\
         &\xrightarrow[{[\pi_1]}]{\sim } H_1(D^{\text{dense}})\xrightarrow[{[\gamma_1]}]{\sim}  \measured
     \end{align}
     \item Similarly, we have:
     \begin{align}
         \syst^1(D^{\text{sparse}}) &\geq \syst^1(D^{\text{gauged}})  \\ &\geq \syst^1(D^{\text{dense}}) \geq \syst^1(C)
