    \item Finally, with $\omega \leq O(1)$ since the input code is sparse:
    \begin{align}
        \dim D^{\text{sparse}}_0 & \leq \dim A_0 + \dim G_0 + O( \omega_\dagger) \dim A_1 \\
        & \leq n + sn + O( s) n \\
        & \leq O(sn) \\
        &\leq O(n (k-\kappa + d \log(n)))
    \end{align} 
    \end{enumerate}

\end{proof}

\subsection{Open Questions}

We have some reasons to think that the scaling given by \Cref{theorem:main} is close to optimal. On one hand (non-fast) parallel surgery can be achieved with $\tilde{O}(nk)$ overhead \cite{cowtan2025parallel}, and requires at least $\Omega(k^2)$ overhead \noue{cite}. On the other, the logical cocyles use to build $\sigma_{\text{cocycles}}$ all have support at least $d$, suggesting the $d \log(n)$ term is also unavoidable. We further note that for constant rate codes our construction is indeed optimal, up to polylogarithmic factors. 

It also remains open how to obtain sparse metachecks. In our construction, the limiting factor is currently the data layers used in \Cref{lemma:dual-gauging-gadget}, as they impose that the modified boundary map $\tilde{\partial}_2^A$ acts densely on those layers. In essence we are still lacking an expansion-preserving gadget that can reduce the degree of $Z$ checks while not increasing the $X$ weight.

\section{Sparsification gadgets}

\subsection{Gauging gadget (weight reducing)}
\label{subsec:gauging}

The following amounts to an exposition of the non-decongested gadgets from \cite{williamson2024gauging} from a chain map perspective. We only need to also show that those gadgets are expansion-preserving.

\begin{lemma}\label{lemma:gauging-gadget}
    Let
    \begin{equation}
        \begin{tikzcd}
        	{A_2} & {A_1} & {A_0} \\
        	& T
        	\arrow[from=1-1, to=1-2]
        	\arrow[from=1-2, to=1-3]
        	\arrow["\sigma", from=1-2, to=2-2]
        \end{tikzcd}
    \end{equation}
    with $\sigma \in \F_2^{s \times n}$
    Then there exists $\mathcal{G}_\bullet$, and $\tau_\bullet$:
    \begin{equation}
        \begin{tikzcd}
        	& {A_2} & {A_1} & {A_0} \\
        	{\mathcal{G}_3} & {\mathcal{G}_2} & {\mathcal{G}_1}
        	\arrow[from=1-2, to=1-3]
        	\arrow["{\tau_2}", from=1-2, to=2-2]
        	\arrow[from=1-3, to=1-4]
        	\arrow["{\tau_1}", from=1-3, to=2-3]
        	\arrow[from=2-1, to=2-2]
        	\arrow[from=2-2, to=2-3]
        \end{tikzcd}
    \end{equation}
    Such that $\fib(\tau)$ satisfies the following properties:
    \begin{enumerate}
        \item Given $\gamma_\bullet$ the natural projection from $\fib(\sigma)$ to $A_\bullet$ such that $\fib(\sigma)$ has the $d$-threshold property relative to $\gamma_1$. 

        Then there exists a map $\pi_\bullet : \fib(\tau) \to \fib(\sigma)$ such that $\gamma_\bullet \circ \pi_\bullet$ is sparse; and $\fib(\tau)$ has the $d$ threshold property relative to $\gamma_1 \circ \pi_1$. 
        \item  The projection $\pi_1$ induces the isomorphism $[\pi_1]: H_1(\fib(\tau)) \xrightarrow{\sim} H_1(\fib(\sigma))$
        \item $\syst^1(\fib(\tau)) \geq \syst^1(\fib(\sigma))$
        \item The map $\tau_1$ is $O(s)$-bounded, while $(\partial_1^{\mathcal{G}})$ $O(1)$-sparse, and $\tau_1^T$ is $1$-bounded
        \item $\dim \mathcal{G}_1 \leq sn$ 
    \end{enumerate}
\end{lemma}

    We begin by writing $\sigma$ as a matrix of $s$ row vectors, each with length $n$:
    \begin{equation}
        \sigma = \begin{bmatrix}
            \quad & \vec{\sigma}_1 & \quad \\ 
            \quad & \vec \sigma_2 & \quad\\
            \quad & \vdots \\
            \quad & \vec \sigma_s &\quad
        \end{bmatrix} 
    \end{equation}

    Then to each of those vectors, we associate a connected expander graph $G_j = (V_j, E_j)$, with $|V_j| = |\supp(\sigma_j)|$ from \Cref{lemma:constant-degree-expanders}, along with an injection $\iota_j: \supp(\sigma_j) \to V_j$. The graphs can each be augmented with faces $F_j$ such that
    \begin{equation}
        H_2(\mathcal{G}^j) = 0, \quad \mathcal{G}^j = \F_2[F_j] \to \F_2[E_j] \to \F_2[V_j]
    \end{equation}
    We then define a chain map $\tau^j: A_\bullet \to \mathcal{G}^j$:
    \begin{equation}
        \tau^j_1(a_1) = \iota(a_1), \quad \tau = \bigoplus_j \tau^j
    \end{equation}
    To define $\tau_2$, we make the observation that $\partial a_2 \in A_1$ has even overlap with all $\vec{\sigma}_j$'s, so we can group this support into disjoint pairs: $\supp(\partial a_2) \cap \supp(\vec{\sigma}_j)\cong \{ (a_l, a_{l+1})\}_{l=1}^{M}$, for some $M \in \N$. As $G_j$ is connected, for each of those pairs, there exists a path $p_j((a,b)) \subset E_j$ in $G_j$, with startpoint $a$, and endpoint $b$. We thus write
    \begin{equation}
        \tau^j_2(a_2) = \bigoplus_j \sum_{(a,b) \in\supp(\partial a_2) \cap \supp(\vec{\sigma}_j) } p_j((a, b))
    \end{equation}
    This gives us the following chain map:
    \begin{equation}
        \begin{tikzcd}
        	& {A_2} & {A_1} & {A_0} \\
        	{\F_2[F_j]} & {\F_2[E_j]} & {\F_2[V_j]}
        	\arrow[from=1-2, to=1-3]
        	\arrow["{\tau_2^j}", from=1-2, to=2-2]
        	\arrow[from=1-3, to=1-4]
        	\arrow["{\tau_1^j}", from=1-3, to=2-3]
        	\arrow[from=2-1, to=2-2]
        	\arrow[from=2-2, to=2-3]
        \end{tikzcd}
    \end{equation}

    We then sum over all the individual graph gadgets. Writing $\mathcal{G} = \bigoplus_j \mathcal{G}^j$, $\tau_\bullet = \bigoplus_j \tau^j_\bullet $, we have:
    \begin{equation}
        \begin{tikzcd}
        	& {A_2} & {A_1} & {A_0} \\
        	{\mathcal{G}_3} & {\mathcal{G}_2} & {\mathcal{G}_1}
        	\arrow[from=1-2, to=1-3]
        	\arrow["{\tau_2}", from=1-2, to=2-2]
        	\arrow[from=1-3, to=1-4]
        	\arrow["{\tau_1}", from=1-3, to=2-3]
        	\arrow[from=2-1, to=2-2]
        	\arrow[from=2-2, to=2-3]
        \end{tikzcd}
    \end{equation}

    \begin{remark}
    Note that we do not use the decongested version of the construction of \cite{williamson2024gauging}, as we are not concerned with the boundedness of the resulting $\partial_2^{\fib(\tau)}$.
    \end{remark}

    \begin{proofof}{\Cref{lemma:gauging-gadget}}
        \begin{enumerate}


            \item 



            Intuitively, that property is preserved simply because the graph gadgets, through $\tau$, preserve the parity of violations of row of $\sigma$, and therefore the weight of the syndrome. The "parity of violations" for the gadgets can be studied formally by focusing on $\tau^*: A_1 \to H_1(\mathcal{G})$ \footnote{Note that $H_1(\mathcal{G}) \cong \F_2^s \cong T$, this hints at $\tau$ preserving the syndrome information given by $\sigma$.}. 

            From the definition of $\tau^j_1$, we read that $\tau^j_1 \ket{a_1} = \ket{\iota(a_1)} \braket{\sigma_j | a_1}$, so $|\supp(\tau^j_1 \ket{\vec{a}})|$ has the same parity as $\braket{\sigma_j|a}$. 
            From $G_j$ being connected, all vectors of the same parity are the same class in $H_1(\mathcal{G}^j)$, hence $(\tau^j_1)^* \cong \sigma_j$; where we write $(\tau^j_1)^* : A_1 \to H_1(\mathcal{G}^j)$. 
            By linearity we obtain $\tau_1^* \cong \sigma$. 

            Consequently, we have $\ker \tau_1^* = \ker \sigma$, which allows us to use the natural projection $\pi_1: A_1 \oplus \mathcal{G}_2 \to A_1$, under which the kernels are preserved:
            \begin{align}
                Z_1(\fib(\sigma)) = \pi_1 Z_1(\fib(\tau))
            \end{align}
            The chain map $\pi_\bullet$ is then given by:
            \begin{align}
                \pi_2 &: A_2 \oplus \mathcal{G}_3 \to A_2, \quad \pi_2(a_2 \oplus g_3) = a_2 \\
                \pi_1&: A_1 \oplus \mathcal{G}_2 \to A_1, \quad \pi_1 (a_1 \oplus g_2)= a_1 \\
                \pi_0&: A_0 \oplus \mathcal{G}_1 \to A_0 \oplus H_0(\mathcal{G}) \cong T \\  
                \pi_0& \ket{a, v} = \ket{a, [v]}
            \end{align}
            All of the maps above are trivially $1$-sparse except $\pi_0$, for which we can verify $\gamma_0 (T) = 0$, i.e. $\gamma_0 \circ \pi_0 = \text{id}_{A_0}$ which is $1$-sparse.

            We then move on to lower bounding the syndrome. First, we trivially have:
            \begin{align}
                &\norm{\partial_1^{\fib(\tau)} \ket{{a}, {e}}} \\
                = &\norm{\tau_1 \ket{{a}} + \partial_2^{\mathcal{G}}\ket{{e}}}  + \norm{\partial_1^{A} \ket a} \\
                = &\norm{\tau_1 \ket{{a}} + \partial_2^{\mathcal{G}}\ket{{e}}}  + \norm{\partial_1^{A} \pi_1 \ket{a,e}}
            \end{align}
            While $\pi_0$ itself is not sparse the composition $\gamma_0 \circ \pi_0$ is, as it eliminates the $T$ component entirely.

            Now we break down the vector $\ket{{e}}$ into graph-wise components, i.e. $\ket{{e}} = \bigoplus_j \ket{e_j}$. This gives 

            \begin{align}
                &\norm{\tau_1 \ket{{a}} + \partial^{\mathcal{G}}\ket{{e}}} \\ =& \norm{\bigoplus_j \tau^j_1 \ket{{a}} + \partial^{\mathcal{G}_j}\ket{e_j}} \\
                \geq & \norm{\bigoplus_j (\tau^j)^* \ket{a}} \cdot \min_j \syst_1(\mathcal{G}^j) \\
                \geq& \norm{\bigoplus_j (\tau^j)^* \ket{a}} =  \norm{\tau^* \ket{a}} \\
                 = & \norm{\sigma \ket{a}}\\
                 = & \norm{\sigma \pi_1 \ket{a, e}}\\
            \end{align}
            Hence 
            \begin{equation}
                \norm{\partial_1^{\fib(\tau)} \ket{{a}, {e}}}  \geq \norm{\partial_1^{\fib(\sigma) } \pi_1 \ket{{a}, {e}}} 
            \end{equation}

            Thus we get that if
            \begin{equation}
                (\gamma_1 \circ \pi_1 ) \ket{a, e} \not \in (\gamma_1 \circ \pi_1) Z_1(\fib(\tau))
            \end{equation}
            Or equivalently, 
            \begin{equation}
                \gamma_1 (\pi_1  \ket{a, e} ) \not \in \gamma_1 (\pi_1 Z_1(\fib(\tau))) = \gamma_1 Z_1(\fib(\sigma)))
            \end{equation}
            Then we get:
            \begin{equation}
                 \norm{\partial_1^{\fib(\tau)} \ket{{a}, {e}}}  \geq \norm{\partial_1^{\fib(\sigma) } \pi_1 \ket{{a}, {e}}} \geq d
            \end{equation}

            \item We already have $\tau_1^* \cong \sigma$, hence $\ker [\tau] = \ker[\sigma]$. 
            Since $H_2(\mathcal{G}) = 0$ from assumptions, we can then compute the homology group of the mapping cone $H_1(\fib(\tau)) = H_1(\fib(\sigma))$ \cite{weibel1994introduction, baspin2025fastsurgeryquantumldpc}.

            \item $\syst^1(\fib(\tau)) \geq \syst^1(\fib(\sigma))$ is preserved from expansion, see \cite{williamson2024gauging}, and also \cite{baspin2025fastsurgeryquantumldpc, yuan2026quantumweightreductionlayer}.

            \item By definition, the $\partial^{\mathcal{G}}_2$ is $2$-bounded, and $(\partial^{\mathcal{G}}_2)^T$ is $d_0$-bounded, hence $\partial^{\mathcal{G}}_2$ is $O(d_0)$-sparse, or $O(1)$-sparse. 

            On the other hand, $\tau_1$ is $s$-bounded, and $\tau^T_1$ is $1$-bounded.



            \item $\dim \mathcal{G}_2 \leq s \cdot \max_j |V_j| \leq sn$ by construction. 
        \end{enumerate}
    \end{proofof}

\begin{remark}
    While we emphasised the mapping fiber picture for the gauging gadgets to simplify proofs, we also briefly sketch how it can be seen as an instance of a code embedding \cite{yuan2026unified}. The point of this remark is to highlight the duality between the gauging gadget, and the dual gauging gadget, which we will express as a generalised layer code. 
    We first write the complex to be sparsified in an embedding-friendly fashion.
    \begin{equation}
        \fib(\sigma) = \begin{tikzcd}
        	{A_2} & {A_1} & {T \oplus A_0}
        	\arrow["{\partial_2^A}", from=1-1, to=1-2]
        	\arrow["\begin{array}{c} \begin{bmatrix} \sigma \\ \partial^A_1 \end{bmatrix} \end{array}", from=1-2, to=1-3]
        \end{tikzcd}
    \end{equation}
    We can modify the gauging construction slightly to use a single graph $G$ on $n$ vertices, without changing the rest of the construction. The height-2 cone corresponding to the code embedding can then be written as follows:
    \begin{align}
        \begin{tikzcd}[ampersand replacement=\&]
        	\&\& {A_2} \\
        	\&\& {A_1} \\
        	{T\otimes \F_2[F]} \& {T \otimes \F_2[E]} \& \begin{array}{c} \begin{matrix} T \otimes \F_2[V] \\\oplus A_0 \end{matrix} \end{array}
        	\arrow["{\partial_2^A}", from=1-3, to=2-3]
        	\arrow["{p = \tau_2}"', from=1-3, to=3-2]
        	\arrow["{ \begin{bmatrix}\tau_1 \\ \partial^A_1 \end{bmatrix} }", from=2-3, to=3-3]
        	\arrow[from=3-1, to=3-2]
        	\arrow[from=3-2, to=3-3]
        \end{tikzcd}
    \end{align}
    This corresponds to replacing \emph{some} of the checks with some larger, sparser, check layers; namely checks are replaced with graph vertices.
    As $H_1(\mathcal{G}) = 0$, the resulting embedded complex then corresponds to the target code:
    \begin{equation}
        A'^{\textbf{g}} \cong \fib(\sigma)
    \end{equation}
    This rephrasing might be useful for the reader, as in the next section we will instead replace qubits with data layers; namely qubits will be replaced with graph vertices.
\end{remark}

\subsection{Dual-gauging gadget (degree reducing)}
\label{subsec:dual-gauging}

In the following section we describe how to reduce the degree of the surgery ancilla. The gadget can essentially be described as a generalised layer code \cite{yuan2026quantumweightreductionlayer, yuan2026unified} where the qubits with very high degree are replaced by clusters of vertices from an expander graph, instead of the usual surface code layer. 

\begin{lemma}[Dual-gauging gadget] \label{lemma:dual-gauging-gadget}
    Let
    \begin{equation}
        B_\bullet = \begin{tikzcd}[ampersand replacement=\&]
	{B_2} \& {G_1 \oplus A_1} \&\& {G_0 \oplus A_0}
	\arrow["{\left[\begin{smallmatrix}
            \partial_2^G \\
            \partial_2^A
        \end{smallmatrix}\right]}", from=1-1, to=1-2]
	\arrow["{\left[\begin{smallmatrix}
            \partial_1^G & \tau_1 \\
            0 & \partial_1^A
        \end{smallmatrix}\right]}", from=1-2, to=1-4]
\end{tikzcd}
    \end{equation}
    Such that $\partial_1^A, \partial_1^G$ are $\omega$-sparse, while  $\tau_1$ is $\omega_\dagger$-bounded and $(\tau_1)^T$ is $\omega$-bounded. 
    Then there exists output code $\tilde{B}_\bullet$:

    \begin{equation}
        \tilde{B}_\bullet = \begin{tikzcd}
        	{\tilde{B}_2} & {G_1 \oplus A_1^{\oplus \omega_\dagger + 1}} & {G_0 \oplus A_0 \oplus Q_0}
        	\arrow["\partial_2^{\tilde{B}}", from=1-1, to=1-2]
        	\arrow["\partial_1^{\tilde{B}}", from=1-2, to=1-3]
        \end{tikzcd}
    \end{equation}

    Such that:
    \begin{enumerate}
        \item 
        Write the reduced complex $A'_\bullet$:
        \begin{equation}
            A_\bullet'  = B_2 \to A_1 \to A_0
        \end{equation}
        There exists a natural map $\tilde{\gamma}_\bullet: B_\bullet \to A_\bullet'$:
        \begin{align}
            \tilde{\gamma}_2&: B_2 \to B_2, \quad \tilde\gamma_2 = \text{id}_{B_2} \\
            \tilde{\gamma}_1&: G_1 \oplus A_1 \to A_1, \quad \tilde\gamma_1(g_1 \oplus a_1) = a_1\\
            \tilde{\gamma}_0&: G_0 \oplus A_0\to A_0, \quad \tilde\gamma_0(g_0 \oplus a_0) = a_0
        \end{align}
        If $B_\bullet$ has the $d$-threshold property relative to $\tilde{\gamma}_1$ for $d = \syst_1(A')$, then there exists a map $\rho_\bullet : \tilde{B}_\bullet \to B_\bullet$ such that $\tilde{\gamma}_\bullet \circ \rho_\bullet$ is sparse; and $\tilde{B}_\bullet$ is $1$-systolic expanding relative to $\tilde{\gamma}_1 \circ \rho_1$.
        \item 
        The map $\rho_1:  \tilde{B}_1\to B_1$ induces an isomorphism $[\rho_1]: H_1(\tilde{B}) \xrightarrow{\sim} H_1(B)$
        \item $\syst^1(\tilde{B}) \geq \syst^1(B)$
        \item $\partial_1^{\tilde{B}}$ is $O(\omega)$-sparse
        \item $\dim \tilde{B}_0 = \dim A_0 + \dim G_0 +  O(\omega_\dagger)\dim A_1$ 
    \end{enumerate}
\end{lemma}

As previously mentioned, our approach relies on replacing the qubits in $A_1$ by some data layers \cite{yuan2026quantumweightreductionlayer, yuan2026unified, williamson2024layer}. 
Using \Cref{lemma:constant-degree-expanders} pick $X = (V,E)$ an $(\omega + 2)$-expander graph on $\omega_\dagger + 1$ vertices, then each qubit in $A_1$ is replaced by a cluster $V$. 
A number $\omega_\dagger$ of those vertices will be used to sparsify $\tau_1$, while the last one will be used for the already sparse $\partial_1^A$. The data layers then correspond to the complex $Q_\bullet$.
\begin{align}
    Q_\bullet =& Q_1 \xrightarrow{\partial^Q_1} Q_0 \\
    =& A_1 \otimes \F_2[V] \xrightarrow{\text{id} \otimes \partial^V} A_1 \otimes \F_2[E]
\end{align}
Note that $Q_1 = A_1^{\oplus \omega_\dagger + 1}$. For convenience, we will use the notation $V = \{ 0, 1, \dots, \omega_\dagger\}$, and $\F_2[V] = \spn\{ \ket{0}, \ket{1}, \dots, \ket{\omega_\dagger}\}$.

Then, the output code $\tilde{B}_\bullet$ is defined as the code embedding obtained from the following height-2 cone 
\begin{equation}
    \begin{tikzcd}
        {B_2} & \\
        {G_1 \oplus Q_1} & {Q_0} \\
        {G_0 \oplus A_0}
        \arrow["f", from=1-1, to=2-1]
        \arrow["{\partial^Q}", from=2-1, to=2-2]
        \arrow["{f'}", from=2-1, to=3-1]
    \end{tikzcd}
\end{equation}
This means we have:
\begin{equation}
    \tilde{B}_\bullet = \begin{tikzcd}
	{B_2} & {G_1 \oplus Q_1} && {G_0 \oplus A_0 \oplus Q_0}
	\arrow["f", from=1-1, to=1-2]
	\arrow["\begin{array}{c} \begin{bmatrix}f' \\ 0 \ \partial^Q \end{bmatrix} \end{array}", from=1-2, to=1-4]
\end{tikzcd}
\end{equation}
The explicit form of the maps above is given as follows:
\begin{equation}
    \begin{tikzcd}[ampersand replacement=\&]
	{B_2} \&\& \\
	\\
	{G_1 \oplus A_1 \otimes \F_2[V]} \&\& {A_1 \otimes \F_2[E]} \\
	\\
	{G_0 \oplus A_0}
	\arrow["{\begin{bmatrix} \partial_2^G \\ \tilde{\partial}_2^{A}  \end{bmatrix}  }"', from=1-1, to=3-1]
	\arrow["{\text{id} \otimes \partial^V}", from=3-1, to=3-3]
	\arrow["{\begin{bmatrix} \partial_1^G & \tilde{\tau}_1 \\ 0 & \tilde{\partial}_1^A \end{bmatrix}}"', from=3-1, to=5-1]
\end{tikzcd}
\end{equation}
Where we write
\begin{equation}
    \tilde{\partial}_2^A = \partial_2^A \otimes \ket{\vec{1}_V}, \qquad \tilde{\partial}_1^A = \partial_1^A \otimes \bra{v_\star}.
\end{equation}
Where $v_\star$ is a distinguished vertex, and we write $\ket{\vec{1}_V} = \sum_{v \in V} \ket{v}$. Thus the original syndrome information from $A_0$ is carried by the distinguished copy $a_1\otimes \ket{v_\star}$.

It remains to sparsify $\tau_1$. Since $\tau_1$ is $\omega_\dagger$-bounded, then for any basis element $a_1 \in A_1$:
\begin{equation}
    \card{\tau_1 (a_1)} \leq \omega_\dagger.
\end{equation}
Choosing $|V|=  \omega_\dagger+1$, we may therefore pick, for each
basis element $a_1$, an injective labeling
\begin{equation}
    \iota_{a_1}: \supp(\tau_1 (a_1)) \to V\setminus\{v_\star\}.
\end{equation}
We then define the twisted map $\tilde{\tau}_1$ by
\begin{equation}
    \tilde{\tau}_1 (a_1\otimes \ket{v}) = \sum_{\substack{g_0 \in \supp(\tau_1 a_1) \\ \iota_{a_1}(g_0) = v}} g_0 
\end{equation}

\begin{proofof}{\Cref{lemma:dual-gauging-gadget}}
    \begin{enumerate}



        \item 
        We start by definition the chain map $\rho_\bullet$. Naturally, we take $\rho_2: \tilde{B}_2 = B_2 \to B_2$ as the identity on $B_2$. 

        We then define $\rho_1: G_1 \oplus A_1 \otimes \F_2[V] \to G_1 \oplus A_1$ as the projection on the distinguished vertex $v_\star\in V$. 
        \begin{equation}
            \rho_1 = \text{id}_G \oplus \text{id}_A \otimes \bra{v_\star}
        \end{equation}

        For $\rho_0$, we begin by assuming a map of the form $\rho_0 (g_0 \oplus a_0\oplus e_0) = (g_0 + \phi(e_0)) \oplus a_0$, for some function $\phi: A_1 \otimes \F_2[E] \to G_0$. Through the commutation condition, we get this map has to obey the following relation:
        \begin{align}
            \label{eq:phi-commutation}
            &\phi \circ (\text{id} \otimes \partial^V) (a \otimes \ket{v} )= \nonumber \\ 
            & \qquad \tau_1 a  \braket{v_\star | v} - \tilde{\tau}_1 (a \otimes \ket{v})
        \end{align}
        We see here that the role of $\phi$ is to resolve the incongruence between $\tau_1 \circ \rho_1$ computing some syndrome reading values only from $\F_2[v_\star]$, while $\tilde{\tau}_1$ computes the syndrome from the entirety of $\F_2[V]$. 

        The simplest solution is to add some correction to the syndrome in $G_0$ whenever the values of $v$ and $v_\star$ differ. From the perspective of $\phi$ this can be accomplished by, along a path from $v \in V$ to $v_\star \in V$ computing the parity of the edges encountered. Write $\ket{\Phi_{v \rightsquigarrow v_\star }} \in \F_2[E]$ a choice of path from $v$ to $v_\star$, and $\ket{\nu} \in \F_2[V]$ an arbitrary state on the vertex space. Then:
        \begin{equation}
            \bra{\Phi_{v \rightsquigarrow v_\star }} \partial^V \ket{\nu} = \braket{v|\nu} - \braket{v_\star|\nu}
        \end{equation}
        Summing over $v$'s we get:
        \begin{align}
            (&\sum_v \ket{v}\bra{\Phi_{v \rightsquigarrow v_\star }}) \partial^V \ket{\nu} \\
            = &\sum_v \ket{v} (\braket{v|\nu} - \braket{v_\star|\nu}) \\
            = &\ket{\nu} - \braket{v_\star|\nu} \ket{\vec{1}_V}
        \end{align}
        Where $\ket{\nu} - \braket{v_\star|\nu} \ket{\vec{1}_V}$ is a vector with value $0$ at $v$ if $\braket{v|\nu} =\braket{v_\star|\nu}$ and $1$ otherwise: it encodes locations that need correction relative to $v_\star$.
        We can then write:
        \begin{gather}
        \Pi: \F_2[E] \to \F_2[V]
        \Pi = \sum_v \ket{v}\bra{\Phi_{v \rightsquigarrow v_\star }} \\
            \phi = \tilde{\tau}_1 \circ (\text{id}_A \otimes \Pi)
        \end{gather}
        And one can readily verify that $\phi$ satisfies equation \Cref{eq:phi-commutation}.
        Note that resulting $\rho_0$ is not a sparse map, due to $\Pi$ computing some parity along potentially long paths. However, since $\tilde{\gamma}_0 (G_0)= 0$, and therefore $\tilde{\gamma}_0  \circ \phi = 0$ we still have $\tilde{\gamma}_0\circ \rho_0$ $1$-sparse. 

        We now move on to lower bound the expansion. Let $\tilde{b} = g\oplus \tilde{a} \in G_1 \oplus A_1 \otimes \F_2[V]$. We write
        \begin{equation}
            \tilde{a}  = \bigoplus_{a} a\otimes \ket{\nu_a}, \quad \ket{\nu_a} \in \F_2[V]
        \end{equation}
        Then for any $\tilde{a}$ there exists a correction $\tilde{a}_{\text{corr}} = \bigoplus_{a} a\otimes \ket{\nu_a^{\text{corr}}}$ with $\ket{\nu_a^{\text{corr}}} \in \F_2[V]$ such that $\ket{\nu_a}+ \ket{\nu_a^{\text{corr}}} \in \ker \partial^V$, and we can pick $\norm{\ket{\nu_a^{\text{corr}}}} \leq |V|/2$.

        We write $\tilde{a}_{\text{dec}} = \tilde{a} + \tilde{a}_{\text{corr}}$ the "decoded" version of $\tilde{a}$. As $\ker\partial^V = \spn\{\ket{\vec{1}_V}\}$, there exists $a_{\text{dec}}$ such that 
        \begin{equation}
            \tilde{a}_{\text{dec}} = a_{\text{dec}} \otimes \ket{\vec{1}_V}
        \end{equation}
        Correspondingly, we write $\tilde{b}_{\text{dec}} = g \oplus \tilde{a}_{\text{dec}}$, and $b_{\text{dec}} = g \oplus a_{\text{dec}}$. Crucially, we have:
        \begin{align}
            \partial_1^{\tilde{B}} \tilde{b}_{\text{dec}} = & f'(\tilde{b}_{\text{dec}}) \\
            = & (\partial_1^G g + \tilde{\tau}_1\tilde{a}_{\text{dec}}) \oplus \tilde{\partial}_1^A \tilde{a}_{\text{dec}} \\ 
            =& (\partial_1^G g + \tau_1 a_{\text{dec}}) \oplus \partial_1^Aa_{\text{dec}} \\
            =& \partial_1^B b_{\text{dec}}
        \end{align}




        We can then compute:
        \begin{align*}
            \norm{\partial_1^{\tilde{B}} \tilde{b}} = & \norm{\partial_1^{\tilde{B}} (\tilde{b}_{\text{dec}} + \tilde{a}_{\text{corr}})} \\

            =  & \norm{f'(\tilde{b}_{\text{dec}}+ \tilde{a}_{\text{corr}} )} + \norm{\text{id} \otimes\partial^V\tilde{a}_{\text{corr}}} \\

            \geq &  \norm{f'(\tilde{b}_{\text{dec}})} - \norm{ \tilde{\tau}_1(\tilde{a}_{\text{corr}})} \\& - \norm{ \tilde{\partial}_1^A(\tilde{a}_{\text{corr}})}+  (\omega+2)\norm{\tilde{a}_{\text{corr}}} \\

            \geq & \norm{\partial_1^B(b_{\text{dec}})} - \norm{\tilde{a}_{\text{corr}}} \\ &- \omega \norm{\tilde{a}_{\text{corr}}} +  (\omega + 2)\norm{\tilde{a}_{\text{corr}}} \\

            \geq &\norm{\partial_1^B(b_{\text{dec}})} +\norm{\tilde{a}_{\text{corr}}}
        \end{align*}

        If $\tilde{\gamma}_1(b_{\text{dec}}) \not \in \tilde{\gamma}_1(Z_1(B))$, then $\norm{\partial_1^B(b_{\text{dec}})} \geq d$ and thus $\norm{\partial_1^{\tilde{B}} \tilde{b}}  \geq d$. 
        Now suppose that $\tilde{\gamma}_1(b_{\text{dec}}) \in \tilde{\gamma}_1(Z_1(B))$.  This means that $\tilde{\gamma}_1 \circ \rho_1 (\tilde{b}_\text{dec}) \in \tilde{\gamma}_1 \circ \rho_1 Z_1(\tilde{B})$. In which case then 
        \begin{align}
            &\dist(\tilde{\gamma}_1 \circ \rho_1 (\tilde{b}), \tilde{\gamma}_1 \circ \rho_1 Z_1(\tilde{B})) \\ 
            & \leq \dist(\tilde{\gamma}_1 \circ \rho_1 ( \tilde{b}), \tilde{\gamma}_1 \circ \rho_1 (\tilde{b}_\text{dec}) ) \\
            & \leq \norm{\tilde{\gamma}_1 \circ \rho_1 ( \tilde{a}_\text{corr})} \\
            & \leq \norm{\tilde{a}_{\text{corr}}} \\
            & \leq \norm{\partial_1^{\tilde{B}} \tilde{b}}
        \end{align}

        Thus $\tilde{B}_\bullet$ is $1$-systolic expanding relative to $\tilde{\gamma}_1 \circ \rho_1$.

        \item We have $Z_1(\tilde{B}) \subset \ker(\text{id} \otimes \partial^V) = G_1 \oplus A_1 \otimes \ket{\vec{1}_V}$. On that space, we have $\tilde{\tau}_1 (a \otimes \ket{ \vec{1}}_V) = \tau_1 (a)$ and $\tilde{\partial}_1^A (a \otimes \ket{ \vec{1}}_V) = \partial_1^A a$.
        Hence, we have $\rho_1 Z_1(\tilde{B}) = Z_1(B)$, and $\rho_1 B_1(\tilde{B}) = B_1(B)$.

        This shows that the projection $\rho_1$ induces the isomorphism $[\rho_1]: H_1(\tilde{B}) \xrightarrow{\sim} H_1(B)$.

        \item We can compute $H^1(\tilde{B})$ from the following embedded co-complex \cite{yuan2026unified}:
        \begin{equation}
            B_2 \leftarrow G_1 \oplus H^1(Q) \leftarrow B_0
        \end{equation}

        As previously noted, the complex $\F_2[V] \to \F_2[E]$ corresponds to a connected graph. Therefore the coboundaries induced by $\F_2[E]$ connect any two vertices, giving $H^1(\mathcal{G}) \cong \F_2$. 
        Here this gives $H^1(Q) = A_1 \otimes H^1(\mathcal{G}) \cong A_1 \otimes \F_2 \cong A_1$. 
        The coboundary maps $(\tilde{\partial}_2^A)^T, (\tilde{\partial}_1^A)^T, (\tilde{\tau}_1)^T$ behave as $(\partial_2^A)^T, (\partial_1^A)^T, (\tau_1)^T$ on $H^1(Q) \cong A_1$; 
        and therefore $(\partial_2^{\tilde{B}})^T, (\partial_1^{\tilde{B}})^T$ act as $(\partial_2^{B})^T, (\partial_1^{B})^T$ on $G_1 \oplus H^1(Q)$, giving:
        \begin{equation}
            \syst^1(\tilde{B}) \geq \syst^1(B)
        \end{equation}


        \item We have that $\tilde{\tau}_1$ is $1$-bounded and $\tilde{\partial}_1^A$ is $\omega$-bounded, while $\text{id} \otimes \partial^V$ is $d_0 \lceil  \frac{\omega+2}{h_0}\rceil$-bounded, or $O(\omega)$-bounded, and $\partial_1^G$ is $\omega$-bounded, hence $\partial_1^{\tilde{B}}$ is $O(\omega)$-bounded.

        On the other hand, we have that $(\tilde{\tau}_1)^T$ is $\omega$-bounded and $(\tilde{\partial}_1^A)^T$ is $\omega$-bounded too, while the transpose of $\text{id} \otimes \partial^V$ is $2$-bounded, and $(\partial_1^G)^T$ is $\omega$-bounded, hence $(\partial_1^{\tilde{B}})^T$ is $O(\omega)$-bounded.

        \item By definition, $\dim Q_0 = O(\omega \omega_\dagger) \dim A_1$, hence $\dim \tilde{B}_0 \leq \dim A_0 + \dim G_0 + O( \omega\omega_\dagger) \dim A_1$
    \end{enumerate}
\end{proofof}

\section{Auxillary lemmas}

\begin{lemma}
\label{lemma:constant-degree-expanders}There exist constants $d_0, h_0$ such that for every $\lambda >0$ there exists a family $\{X_m\}_{m\ge 1}$ of $d_0 \lceil \frac{\lambda}{h_0}\rceil$-regular graphs $X_m$ on $m$ vertices with 
\begin{equation}
    h(X_m) = \min_{\substack{ 0<|S|\le |V(X_m)|/2}} \frac{|E(S,V(X_m)\setminus S)|}{|S|} \geq \lambda
\end{equation}
\end{lemma}
\begin{proof}
    It suffices to take $\lceil \frac{\lambda}{h_0}\rceil$ copies of the graphs from Lemma 2.1 of \cite{dinur2007pcp}.
\end{proof}

\begin{lemma}[Random coding boosting]
    \label{lemma:random-coding-boosting}
    Let $P: \F_2^n \to \F_2^m$, and
    \begin{equation}
        S_d = \{ c \in \im P: 0< \norm{c} < d\}
    \end{equation}
    there exists $R: \mathbb{F}_2^m \to \mathbb{F}_2^t$, such that
    \begin{equation}
        \forall c \in S_d, \quad  \norm{R c} \geq d
    \end{equation}
    With



    \begin{equation}
        t \leq O\left(d \log(em/d)\right)
    \end{equation}
\end{lemma}
\begin{proof}
    We closely follow the proof of Theorem 4.2.1 in \cite{guruswami2025essential}.
    Pick a random matrix $R \in \F_2^{t \times m}$. Then for any $c \in \F_2^m$ the vector $R c$ is random, hence:
    \begin{align}
        \Pr[\norm{Rc} < d] \leq \frac{\{\text{\# of $\F_2^t$ vectors of weight $ \leq d-1 $}\}}{\{\text{\# of vectors in $\F_2^t$}\}} 
    \end{align}
    The numerator is controlled by a sum of binomial coefficients
    \begin{equation}
        \{\text{\# of $\F_2^t$ vectors of weight $ \leq d-1 $}\} \leq \sum_{i=0}^{i = d-1} \binom{t}{i}
    \end{equation}
    With $H_2$ the binary entropy function, we have the following upper bound:
    \begin{equation}
        \sum_{i=0}^{i = d-1} \binom{t}{i} \leq 2^{t H_2((d-1)/t)}
    \end{equation}
    As we can always take $t \geq 4(d-1)$ as it does not contradict the desired result, we have $H_2((d-1)/t)$ an upper bounded constant, which we write $ \epsilon = H_2((d-1)/t) < 1$.
    Using a union bound we get:
    \begin{equation}
        \label{eq:probability-expansion}
        \Pr[\exists c\in S_d: \norm{Rc} < d] \leq \card{S_d} \cdot 2^{-(1-\epsilon) t}
    \end{equation}
    As long as $\card{S_d} < 2^{(1-\epsilon) t}$ then \Cref{eq:probability-expansion} gives that the probability of failure is less than $1$, and therefore there exists a suitable matrix $R$. For that condition to be satisfied it is sufficient to take
    \begin{equation}
        (1-\epsilon)t > \log\card{S_d}
    \end{equation}
    From \cite{jukna2011extremal} Proposition 1.4 we have the following upper bound:
    \begin{equation}
    \card{S_d} \leq \sum_{i=0}^{i=d-1} \binom{m}{i} \leq \left(\frac{e m}{d}\right)^d
    \end{equation}
    We then choose, for some sufficiently large constants:
    \begin{equation}
        t = \Theta(d \log(em/d))
    \end{equation}

\end{proof}

